def serializar(raiz: "Nodo | None") -> str:
    """Serializa árbol a string (preorden con None=N)."""
    if raiz is None:
        return "N"
    return f"{raiz.val},{serializar(raiz.izq)},{serializar(raiz.der)}"

def deserializar(data: str) -> "Nodo | None":
    tokens = iter(data.split(","))
    def helper():
        val = next(tokens)
        if val == "N":
            return None
        nodo = Nodo(int(val))
        nodo.izq = helper()
        nodo.der = helper()
        return nodo
    return helper()

